for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/charlie947/social-media-skills","slug":"social-media-skills-f6215b90","name":"Social Media Skills","type":"SKILL","status":"CANDIDATE","tagline":"Đừng chỉ nhờ AI viết một bài. Hãy cho nó một bộ phận content có chung giọng thương hiệu.","description":"Social Media Skills của Charlie Hills là bộ hướng dẫn giúp AI agent làm nội dung theo một hệ thống nhất quán: hiểu người viết trước, rồi mới viết bài, lên ý tưởng video và tạo hình. Nền tảng là voice-builder, tạo about-me.md và voice.md từ phỏng vấn cùng 3–5 bài mẫu. Các skill còn lại đọc chung hai tệp này, thay vì mỗi lần lại viết một giọng khác nhau.","long_description":"ĐIỂM NỔI BẬT\n• Voice Builder và Newsletter Voice xây hồ sơ tác giả, giọng văn và quy tắc newsletter.\n• Post Writer, Hook Generator, Content Matrix và Post Formatter hỗ trợ viết LinkedIn, tạo mở bài và phát triển ý tưởng theo nhiều khuôn nội dung.\n• Reels Scripting và YouTube Thumbnail chuyển đề tài thành kịch bản video hoặc prompt thumbnail; Gemini Carousel và Infographic hỗ trợ phần hình.\n• Niche Research tìm chuyện mới trong ngách; Post Scorer và Analytics Dashboard dùng dữ liệu bài viết để góp ý, không chỉ chấm theo cảm tính.\n• README hiện ghi tác giả có hơn 415K followers và 100 triệu lượt xem/năm. Đây là số liệu tác giả tự công bố, không phải hiệu quả Windi kiểm chứng hay cam kết cho người cài skill.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nĐưa 3–5 bài viết của bạn vào voice-builder, tạo một newsletter gốc rồi yêu cầu chuyển thành bài LinkedIn, kịch bản Reel và carousel. Đọc lại từng bản trước khi đăng.\n\nBẮT ĐẦU\nCài qua marketplace Claude Code hoặc tải riêng thư mục skill theo README. Chạy voice-builder trước; một số nhánh cần Claude for Chrome, Apify hoặc Gemini và tài khoản tương ứng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nSkill không tự bảo đảm follower, lượt xem hay độ chính xác. Dữ liệu cá nhân và bài mẫu có thể đi tới dịch vụ AI bạn chọn. Chi phí agent, Apify/Gemini và khả năng dùng tiếng Việt cần kiểm tra riêng.","canonical_url":"https://github.com/charlie947/social-media-skills","repository_url":"https://github.com/charlie947/social-media-skills","documentation_url":"https://raw.githubusercontent.com/charlie947/social-media-skills/main/README.md","owner_name":"charlie947","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":1,"categories":["social","content","video"],"primaryCategory":"social","selectionReason":"Phù hợp Social & Marketing: Đừng chỉ nhờ AI viết một bài. Hãy cho nó một bộ phận content có chung giọng thương hiệu. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Đừng chỉ nhờ AI viết một bài. Hãy cho nó một bộ phận content có chung giọng thương hiệu.","highlights":["Voice Builder và Newsletter Voice xây hồ sơ tác giả, giọng văn và quy tắc newsletter.","Post Writer, Hook Generator, Content Matrix và Post Formatter hỗ trợ viết LinkedIn, tạo mở bài và phát triển ý tưởng theo nhiều khuôn nội dung.","Reels Scripting và YouTube Thumbnail chuyển đề tài thành kịch bản video hoặc prompt thumbnail; Gemini Carousel và Infographic hỗ trợ phần hình.","Niche Research tìm chuyện mới trong ngách; Post Scorer và Analytics Dashboard dùng dữ liệu bài viết để góp ý, không chỉ chấm theo cảm tính.","README hiện ghi tác giả có hơn 415K followers và 100 triệu lượt xem/năm. Đây là số liệu tác giả tự công bố, không phải hiệu quả Windi kiểm chứng hay cam kết cho người cài skill."],"example":"Đưa 3–5 bài viết của bạn vào voice-builder, tạo một newsletter gốc rồi yêu cầu chuyển thành bài LinkedIn, kịch bản Reel và carousel. Đọc lại từng bản trước khi đăng.","setup":"Cài qua marketplace Claude Code hoặc tải riêng thư mục skill theo README. Chạy voice-builder trước; một số nhánh cần Claude for Chrome, Apify hoặc Gemini và tài khoản tương ứng.","limitations":"Skill không tự bảo đảm follower, lượt xem hay độ chính xác. Dữ liệu cá nhân và bài mẫu có thể đi tới dịch vụ AI bạn chọn. Chi phí agent, Apify/Gemini và khả năng dùng tiếng Việt cần kiểm tra riêng.","github":{"stars":3189,"forks":747,"observedAt":"2026-09-03T16:07:36.757Z","url":"https://github.com/charlie947/social-media-skills","pushedAt":"2026-08-30T01:06:51Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/charlie947/social-media-skills/main/README.md","observedAt":"2026-09-03T16:09:18.501Z","sha256":"6145e1ca9ad0bf448d857b64009303a720fc9bc3e0fbf0ec3f6171ccf4b79bca"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"charlie947/social-media-skills:metadata","source_url":"https://github.com/charlie947/social-media-skills","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Acharlie947%2Fsocial-media-skills%20repo%3Agitroomhq%2Fpostiz-app%20repo%3Ainovector%2Fmixpost%20repo%3Atrypostit%2Ftrypost%20repo%3Aleamsigc%2FMagicSync%20repo%3Amautic%2Fmautic%20repo%3Aknadh%2Flistmonk%20repo%3Auseplunk%2Fplunk&per_page=100","stars":3189,"forks":747,"license":"MIT"},"fetched_at":"2026-09-03T16:07:36.757Z"},{"source_type":"github","source_identifier":"charlie947/social-media-skills:readme:6145e1ca9ad0bf448d857b64009303a720fc9bc3e0fbf0ec3f6171ccf4b79bca","source_url":"https://raw.githubusercontent.com/charlie947/social-media-skills/main/README.md","raw_metadata":{"sha256":"6145e1ca9ad0bf448d857b64009303a720fc9bc3e0fbf0ec3f6171ccf4b79bca","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:18.501Z"}],"expected":null},{"identity":"repo:https://github.com/coreyhaines31/marketingskills","slug":"marketing-skills-827e7f08","name":"Marketing Skills","type":"SKILL","status":"CANDIDATE","tagline":"Cho AI hiểu sản phẩm trước khi yêu cầu nó viết quảng cáo, landing page hay bài SEO.","description":"Marketing Skills của Corey Haines tổ chức công việc marketing thành các skill dùng chung bối cảnh sản phẩm, khách hàng và định vị. Từ nền tảng product-marketing, bạn có thể đi tiếp sang copywriting, SEO, tối ưu chuyển đổi, social, email và đo lường. Điểm đáng chú ý là các bước có liên hệ với nhau, thay vì một kho prompt rời rạc.","long_description":"ĐIỂM NỔI BẬT\n• Product-marketing làm hồ sơ nền để các skill khác hiểu đúng sản phẩm và người mua.\n• Kết hợp copywriting, CRO và A/B testing; nối SEO audit, schema và AI SEO.\n• Có nhóm social, video, image, ad creative và customer research phục vụ đội nội dung.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNhập thông tin một khóa học, làm rõ người học mục tiêu rồi nhờ AI đề xuất landing page và loạt bài social bám cùng định vị.\n\nBẮT ĐẦU\nCài các skill cần thiết bằng phương thức trong README, mở với agent hỗ trợ Agent Skills và xây bối cảnh sản phẩm trước.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần dữ liệu đầu vào và quyền truy cập công cụ đo lường phù hợp. Gợi ý SEO hay CRO không bảo đảm lên top hoặc tăng doanh số; tích hợp dịch vụ có thể phát sinh phí.","canonical_url":"https://github.com/coreyhaines31/marketingskills","repository_url":"https://github.com/coreyhaines31/marketingskills","documentation_url":"https://raw.githubusercontent.com/coreyhaines31/marketingskills/main/README.md","owner_name":"coreyhaines31","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":2,"categories":["content","seo","social"],"primaryCategory":"content","selectionReason":"Phù hợp Content & Viết lách: Cho AI hiểu sản phẩm trước khi yêu cầu nó viết quảng cáo, landing page hay bài SEO. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Cho AI hiểu sản phẩm trước khi yêu cầu nó viết quảng cáo, landing page hay bài SEO.","highlights":["Product-marketing làm hồ sơ nền để các skill khác hiểu đúng sản phẩm và người mua.","Kết hợp copywriting, CRO và A/B testing; nối SEO audit, schema và AI SEO.","Có nhóm social, video, image, ad creative và customer research phục vụ đội nội dung."],"example":"Nhập thông tin một khóa học, làm rõ người học mục tiêu rồi nhờ AI đề xuất landing page và loạt bài social bám cùng định vị.","setup":"Cài các skill cần thiết bằng phương thức trong README, mở với agent hỗ trợ Agent Skills và xây bối cảnh sản phẩm trước.","limitations":"Cần dữ liệu đầu vào và quyền truy cập công cụ đo lường phù hợp. Gợi ý SEO hay CRO không bảo đảm lên top hoặc tăng doanh số; tích hợp dịch vụ có thể phát sinh phí.","github":{"stars":46743,"forks":7278,"observedAt":"2026-09-03T16:07:43.074Z","url":"https://github.com/coreyhaines31/marketingskills","pushedAt":"2026-09-02T07:43:12Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/coreyhaines31/marketingskills/main/README.md","observedAt":"2026-09-03T16:09:21.519Z","sha256":"fb54b4593f40ad8ac83e556968c3af57d4e53c31d3d6fc06aae4f40ee5d42f6f"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"coreyhaines31/marketingskills:metadata","source_url":"https://github.com/coreyhaines31/marketingskills","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aresend%2Freact-email%20repo%3Amjmlio%2Fmjml%20repo%3Acoreyhaines31%2Fmarketingskills%20repo%3Ablader%2Fhumanizer%20repo%3Adanielmiessler%2Ffabric%20repo%3Amsitarzewski%2Fagency-agents%20repo%3AOpenClaudia%2Fopenclaudia-skills%20repo%3Arealkimbarrett%2Fadvertising-skills&per_page=100","stars":46743,"forks":7278,"license":"MIT"},"fetched_at":"2026-09-03T16:07:43.074Z"},{"source_type":"github","source_identifier":"coreyhaines31/marketingskills:readme:fb54b4593f40ad8ac83e556968c3af57d4e53c31d3d6fc06aae4f40ee5d42f6f","source_url":"https://raw.githubusercontent.com/coreyhaines31/marketingskills/main/README.md","raw_metadata":{"sha256":"fb54b4593f40ad8ac83e556968c3af57d4e53c31d3d6fc06aae4f40ee5d42f6f","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:21.519Z"}],"expected":null},{"identity":"repo:https://github.com/gitroomhq/postiz-app","slug":"postiz-077e6de3","name":"Postiz","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một lịch nội dung cho nhiều kênh, thay vì mỗi ngày mở từng mạng xã hội để đăng bài.","description":"Postiz là nền tảng quản lý và lên lịch mạng xã hội có các tính năng AI, analytics và cộng tác. Điểm đáng chú ý với creator là tập trung khâu phân phối: soạn nội dung, chuẩn bị lịch đăng, phối hợp với cộng sự và theo dõi kết quả trong cùng hệ thống. Repo cũng dẫn tới API, tích hợp n8n và công cụ cho AI agent.","long_description":"ĐIỂM NỔI BẬT\n• Lên lịch bài và quản lý hoạt động social tập trung.\n• Cộng tác với thành viên nhóm, nhận xét và theo dõi hiệu quả qua analytics.\n• API cùng tích hợp n8n/Make giúp nối lịch đăng với quy trình tạo nội dung.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nChuẩn bị loạt bài giới thiệu sản phẩm, điều chỉnh bản viết cho từng kênh rồi xếp lịch cả tuần; dùng số liệu sau đăng để chọn góc nội dung tiếp theo.\n\nBẮT ĐẦU\nChọn bản dịch vụ hoặc làm theo Quick Start tự triển khai của Postiz. Kết nối tài khoản qua luồng xác thực chính thức của từng nền tảng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nTự host vẫn cần máy chủ và cấu hình tích hợp. Quyền đăng, định dạng và analytics phụ thuộc API từng mạng xã hội; không được suy ra rằng mọi kênh đều hỗ trợ mọi tính năng. Không phải công cụ bảo đảm tăng trưởng.","canonical_url":"https://github.com/gitroomhq/postiz-app","repository_url":"https://github.com/gitroomhq/postiz-app","documentation_url":"https://raw.githubusercontent.com/gitroomhq/postiz-app/main/README.md","owner_name":"gitroomhq","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":3,"categories":["social","automation"],"primaryCategory":"social","selectionReason":"Phù hợp Social & Marketing: Một lịch nội dung cho nhiều kênh, thay vì mỗi ngày mở từng mạng xã hội để đăng bài. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một lịch nội dung cho nhiều kênh, thay vì mỗi ngày mở từng mạng xã hội để đăng bài.","highlights":["Lên lịch bài và quản lý hoạt động social tập trung.","Cộng tác với thành viên nhóm, nhận xét và theo dõi hiệu quả qua analytics.","API cùng tích hợp n8n/Make giúp nối lịch đăng với quy trình tạo nội dung."],"example":"Chuẩn bị loạt bài giới thiệu sản phẩm, điều chỉnh bản viết cho từng kênh rồi xếp lịch cả tuần; dùng số liệu sau đăng để chọn góc nội dung tiếp theo.","setup":"Chọn bản dịch vụ hoặc làm theo Quick Start tự triển khai của Postiz. Kết nối tài khoản qua luồng xác thực chính thức của từng nền tảng.","limitations":"Tự host vẫn cần máy chủ và cấu hình tích hợp. Quyền đăng, định dạng và analytics phụ thuộc API từng mạng xã hội; không được suy ra rằng mọi kênh đều hỗ trợ mọi tính năng. Không phải công cụ bảo đảm tăng trưởng.","github":{"stars":35428,"forks":6740,"observedAt":"2026-09-03T16:07:36.757Z","url":"https://github.com/gitroomhq/postiz-app","pushedAt":"2026-09-03T13:50:43Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/gitroomhq/postiz-app/main/README.md","observedAt":"2026-09-03T16:09:14.516Z","sha256":"9f78ae6fb224f6375e26a26998b70c4e3484625ccdbca9674838546d637ef6d4"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"gitroomhq/postiz-app:metadata","source_url":"https://github.com/gitroomhq/postiz-app","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Acharlie947%2Fsocial-media-skills%20repo%3Agitroomhq%2Fpostiz-app%20repo%3Ainovector%2Fmixpost%20repo%3Atrypostit%2Ftrypost%20repo%3Aleamsigc%2FMagicSync%20repo%3Amautic%2Fmautic%20repo%3Aknadh%2Flistmonk%20repo%3Auseplunk%2Fplunk&per_page=100","stars":35428,"forks":6740,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:36.757Z"},{"source_type":"github","source_identifier":"gitroomhq/postiz-app:readme:9f78ae6fb224f6375e26a26998b70c4e3484625ccdbca9674838546d637ef6d4","source_url":"https://raw.githubusercontent.com/gitroomhq/postiz-app/main/README.md","raw_metadata":{"sha256":"9f78ae6fb224f6375e26a26998b70c4e3484625ccdbca9674838546d637ef6d4","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:14.516Z"}],"expected":null},{"identity":"repo:https://github.com/remotion-dev/remotion","slug":"remotion-f56eb624","name":"Remotion","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một template video có thể trở thành cả series, chỉ bằng cách thay dữ liệu và nội dung.","description":"Remotion lấy React làm nguồn của video, cho phép tạo cảnh, chữ, hiệu ứng và media bằng code hoặc với sự hỗ trợ của AI coding agent. Điểm mạnh cho creator là khả năng kiểm soát và tái sử dụng: một hệ thống hình ảnh có thể xuất nhiều video cùng nhận diện. Nó không phải mô hình tự sinh cảnh quay từ prompt.","long_description":"ĐIỂM NỔI BẬT\n• Tạo video theo cách lập trình, qua agent hoặc công cụ tương tác được hệ sinh thái cung cấp.\n• Có tài liệu về transition, captions, âm thanh, template và player.\n• Hỗ trợ render theo lô và xây thư viện tài nguyên chuyển động cho thương hiệu.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nXây một mẫu Shorts có mở đầu, cảnh giải thích và phụ đề theo timestamp; thay script, voice và hình để tạo các tập cùng phong cách.\n\nBẮT ĐẦU\nChuẩn bị Node.js, chọn template và đọc phần Agent Skills/Getting Started. Nhờ người có kỹ thuật hoặc agent hỗ trợ bước dựng project đầu tiên.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nRemotion có giấy phép riêng và một số trường hợp cần giấy phép công ty; không gọi là MIT hoặc miễn phí vô điều kiện. Chi phí render, công cụ AI và tài nguyên media tính riêng.","canonical_url":"https://github.com/remotion-dev/remotion","repository_url":"https://github.com/remotion-dev/remotion","documentation_url":"https://raw.githubusercontent.com/remotion-dev/remotion/main/README.md","owner_name":"remotion-dev","license":"Remotion License riêng; có trường hợp cần company license. Đọc LICENSE chính chủ.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":4,"categories":["video","design","automation"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Một template video có thể trở thành cả series, chỉ bằng cách thay dữ liệu và nội dung. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một template video có thể trở thành cả series, chỉ bằng cách thay dữ liệu và nội dung.","highlights":["Tạo video theo cách lập trình, qua agent hoặc công cụ tương tác được hệ sinh thái cung cấp.","Có tài liệu về transition, captions, âm thanh, template và player.","Hỗ trợ render theo lô và xây thư viện tài nguyên chuyển động cho thương hiệu."],"example":"Xây một mẫu Shorts có mở đầu, cảnh giải thích và phụ đề theo timestamp; thay script, voice và hình để tạo các tập cùng phong cách.","setup":"Chuẩn bị Node.js, chọn template và đọc phần Agent Skills/Getting Started. Nhờ người có kỹ thuật hoặc agent hỗ trợ bước dựng project đầu tiên.","limitations":"Remotion có giấy phép riêng và một số trường hợp cần giấy phép công ty; không gọi là MIT hoặc miễn phí vô điều kiện. Chi phí render, công cụ AI và tài nguyên media tính riêng.","github":{"stars":58196,"forks":4428,"observedAt":"2026-09-03T16:08:09.166Z","url":"https://github.com/remotion-dev/remotion","pushedAt":"2026-09-03T14:46:13Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/remotion-dev/remotion/main/README.md","observedAt":"2026-09-03T16:09:43.014Z","sha256":"c0aa4732decbd340d28ed59c805605820c3a6ade67b34933d2fad1c8bc0a603d"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"remotion-dev/remotion:metadata","source_url":"https://github.com/remotion-dev/remotion","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Atowfiqi%2Fserpbear%20repo%3Aumami-software%2Fumami%20repo%3Aplausible%2Fanalytics%20repo%3Amatomo-org%2Fmatomo%20repo%3Aposthog%2Fposthog%20repo%3Aremotion-dev%2Fremotion%20repo%3Aheygen-com%2Fhyperframes%20repo%3Aharry0703%2FMoneyPrinterTurbo&per_page=100","stars":58196,"forks":4428,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:08:09.166Z"},{"source_type":"github","source_identifier":"remotion-dev/remotion:readme:c0aa4732decbd340d28ed59c805605820c3a6ade67b34933d2fad1c8bc0a603d","source_url":"https://raw.githubusercontent.com/remotion-dev/remotion/main/README.md","raw_metadata":{"sha256":"c0aa4732decbd340d28ed59c805605820c3a6ade67b34933d2fad1c8bc0a603d","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:43.014Z"}],"expected":null},{"identity":"repo:https://github.com/harry0703/moneyprinterturbo","slug":"moneyprinterturbo-0f1c424d","name":"MoneyPrinterTurbo","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Từ một chủ đề tới bản nháp video: kịch bản, voice, hình, phụ đề và nhạc trong cùng quy trình.","description":"MoneyPrinterTurbo tổ chức chuỗi sản xuất video ngắn từ chủ đề hoặc từ khóa. Bạn có thể để hệ thống tạo từng phần hoặc đưa kịch bản, hình/video và voice riêng vào. Đây là ứng viên sát nhu cầu creator muốn thử workflow tổng thể; tên dự án không có nghĩa dùng nó sẽ tự động kiếm tiền.","long_description":"ĐIỂM NỔI BẬT\n• Có WebUI, API, CLI và đường dùng qua agent; hỗ trợ tùy chỉnh từng khâu.\n• Kết hợp kịch bản đa ngôn ngữ, voice, tư liệu, phụ đề, nhạc và ghép thành phẩm.\n• Hỗ trợ khung dọc, ngang, vuông và tạo theo lô; README có video minh họa đầu ra.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nĐưa kịch bản 45 giây đã duyệt cùng bộ ảnh của bạn, chọn voice và kiểu phụ đề rồi xuất bản nháp để sửa nhịp, hình và phát âm trước khi đăng.\n\nBẮT ĐẦU\nTheo hướng dẫn chính chủ, chuẩn bị Python và các dịch vụ mô hình/media cần dùng. Chọn từng provider có nguồn rõ ràng, không mặc định dùng dịch vụ quảng cáo trong README.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông bảo đảm video khớp hình, phát âm tiếng Việt hay có bản quyền tư liệu. Tạo hàng loạt và kết nối đăng social cần giới hạn quyền, chi phí và bước duyệt con người. Windi chưa chạy thử toàn bộ pipeline.","canonical_url":"https://github.com/harry0703/MoneyPrinterTurbo","repository_url":"https://github.com/harry0703/MoneyPrinterTurbo","documentation_url":"https://raw.githubusercontent.com/harry0703/MoneyPrinterTurbo/main/README.md","owner_name":"harry0703","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":5,"categories":["video","content","social"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Từ một chủ đề tới bản nháp video: kịch bản, voice, hình, phụ đề và nhạc trong cùng quy trình. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Từ một chủ đề tới bản nháp video: kịch bản, voice, hình, phụ đề và nhạc trong cùng quy trình.","highlights":["Có WebUI, API, CLI và đường dùng qua agent; hỗ trợ tùy chỉnh từng khâu.","Kết hợp kịch bản đa ngôn ngữ, voice, tư liệu, phụ đề, nhạc và ghép thành phẩm.","Hỗ trợ khung dọc, ngang, vuông và tạo theo lô; README có video minh họa đầu ra."],"example":"Đưa kịch bản 45 giây đã duyệt cùng bộ ảnh của bạn, chọn voice và kiểu phụ đề rồi xuất bản nháp để sửa nhịp, hình và phát âm trước khi đăng.","setup":"Theo hướng dẫn chính chủ, chuẩn bị Python và các dịch vụ mô hình/media cần dùng. Chọn từng provider có nguồn rõ ràng, không mặc định dùng dịch vụ quảng cáo trong README.","limitations":"Không bảo đảm video khớp hình, phát âm tiếng Việt hay có bản quyền tư liệu. Tạo hàng loạt và kết nối đăng social cần giới hạn quyền, chi phí và bước duyệt con người. Windi chưa chạy thử toàn bộ pipeline.","github":{"stars":120162,"forks":18408,"observedAt":"2026-09-03T16:08:09.166Z","url":"https://github.com/harry0703/MoneyPrinterTurbo","pushedAt":"2026-09-02T14:01:53Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/harry0703/MoneyPrinterTurbo/main/README.md","observedAt":"2026-09-03T16:09:42.287Z","sha256":"6a78488472c1c81736860eb1dca6540ce9cb924565ab752dc2615b5a5df4e91e"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"harry0703/MoneyPrinterTurbo:metadata","source_url":"https://github.com/harry0703/MoneyPrinterTurbo","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Atowfiqi%2Fserpbear%20repo%3Aumami-software%2Fumami%20repo%3Aplausible%2Fanalytics%20repo%3Amatomo-org%2Fmatomo%20repo%3Aposthog%2Fposthog%20repo%3Aremotion-dev%2Fremotion%20repo%3Aheygen-com%2Fhyperframes%20repo%3Aharry0703%2FMoneyPrinterTurbo&per_page=100","stars":120162,"forks":18408,"license":"MIT"},"fetched_at":"2026-09-03T16:08:09.166Z"},{"source_type":"github","source_identifier":"harry0703/MoneyPrinterTurbo:readme:6a78488472c1c81736860eb1dca6540ce9cb924565ab752dc2615b5a5df4e91e","source_url":"https://raw.githubusercontent.com/harry0703/MoneyPrinterTurbo/main/README.md","raw_metadata":{"sha256":"6a78488472c1c81736860eb1dca6540ce9cb924565ab752dc2615b5a5df4e91e","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:42.287Z"}],"expected":null},{"identity":"repo:https://github.com/heygen-com/hyperframes","slug":"hyperframes-c632cefe","name":"HyperFrames","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Viết bố cục như một trang web, rồi xuất thành video MP4 có thể kiểm soát theo thời gian.","description":"HyperFrames của HeyGen chuyển HTML, CSS, media và animation có thể tua thành video. Dự án đi kèm skills để agent lập kế hoạch, viết bố cục, gắn chuyển động, kiểm tra, preview rồi render. Đây là hướng phù hợp với video giới thiệu sản phẩm, đồ họa chữ và explainer, không phải đồng nghĩa có sẵn toàn bộ tính năng avatar của HeyGen.","long_description":"ĐIỂM NỔI BẬT\n• Render video từ HTML/CSS và tài nguyên media qua CLI.\n• Skills hướng dẫn vòng sản xuất có bước lint, preview và xuất video.\n• Có workflow cho giới thiệu website/sản phẩm, faceless explainer và các dạng trình bày khác.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nDùng screenshot sản phẩm của bạn để làm clip giới thiệu 30 giây, thêm tiêu đề chuyển động, voice và nhạc rồi preview từng đoạn trước khi render.\n\nBẮT ĐẦU\nTheo Quick Start chính chủ, cài core skills cần thiết và môi trường CLI. Không cần cài mọi skill cùng lúc.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần làm quen project web hoặc có agent hỗ trợ. Phải kiểm tra animation tua đúng thời gian và quyền của media; phí mô hình/giọng nói bên ngoài không nằm trong giấy phép Apache của framework.","canonical_url":"https://github.com/heygen-com/hyperframes","repository_url":"https://github.com/heygen-com/hyperframes","documentation_url":"https://raw.githubusercontent.com/heygen-com/hyperframes/main/README.md","owner_name":"heygen-com","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":6,"categories":["video","design","content"],"primaryCategory":"video","selectionReason":"Phù hợp Video & Phụ đề: Viết bố cục như một trang web, rồi xuất thành video MP4 có thể kiểm soát theo thời gian. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Viết bố cục như một trang web, rồi xuất thành video MP4 có thể kiểm soát theo thời gian.","highlights":["Render video từ HTML/CSS và tài nguyên media qua CLI.","Skills hướng dẫn vòng sản xuất có bước lint, preview và xuất video.","Có workflow cho giới thiệu website/sản phẩm, faceless explainer và các dạng trình bày khác."],"example":"Dùng screenshot sản phẩm của bạn để làm clip giới thiệu 30 giây, thêm tiêu đề chuyển động, voice và nhạc rồi preview từng đoạn trước khi render.","setup":"Theo Quick Start chính chủ, cài core skills cần thiết và môi trường CLI. Không cần cài mọi skill cùng lúc.","limitations":"Cần làm quen project web hoặc có agent hỗ trợ. Phải kiểm tra animation tua đúng thời gian và quyền của media; phí mô hình/giọng nói bên ngoài không nằm trong giấy phép Apache của framework.","github":{"stars":43818,"forks":4203,"observedAt":"2026-09-03T16:08:09.166Z","url":"https://github.com/heygen-com/hyperframes","pushedAt":"2026-09-03T14:05:29Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/heygen-com/hyperframes/main/README.md","observedAt":"2026-09-03T16:09:43.797Z","sha256":"e497951f5e426ec15888f08d8698aa9365eccdca243e0e50a7cf30ccdacfe2c8"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"heygen-com/hyperframes:metadata","source_url":"https://github.com/heygen-com/hyperframes","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Atowfiqi%2Fserpbear%20repo%3Aumami-software%2Fumami%20repo%3Aplausible%2Fanalytics%20repo%3Amatomo-org%2Fmatomo%20repo%3Aposthog%2Fposthog%20repo%3Aremotion-dev%2Fremotion%20repo%3Aheygen-com%2Fhyperframes%20repo%3Aharry0703%2FMoneyPrinterTurbo&per_page=100","stars":43818,"forks":4203,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:09.166Z"},{"source_type":"github","source_identifier":"heygen-com/hyperframes:readme:e497951f5e426ec15888f08d8698aa9365eccdca243e0e50a7cf30ccdacfe2c8","source_url":"https://raw.githubusercontent.com/heygen-com/hyperframes/main/README.md","raw_metadata":{"sha256":"e497951f5e426ec15888f08d8698aa9365eccdca243e0e50a7cf30ccdacfe2c8","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:43.797Z"}],"expected":null},{"identity":"repo:https://github.com/comfy-org/comfyui","slug":"comfyui-be71f481","name":"ComfyUI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Biến cách tạo hình và video của bạn thành workflow nhìn thấy được, lưu lại được.","description":"ComfyUI dùng các nút nối nhau để tổ chức mô hình, input và từng bước xử lý media. Với creator, giá trị lớn là tái dùng workflow và kiểm soát đầu ra cho cả series. Nó không phải một model duy nhất và tải workflow không đồng nghĩa máy đã có đủ model/node.","long_description":"ĐIỂM NỔI BẬT\n• Workflow hình, video, audio và 3D; lưu/đọc JSON và subgraph.\n• Có template, App Mode và API để tích hợp pipeline.\n• Quản lý hàng đợi, bộ nhớ và chạy lại phần thay đổi trong đồ thị.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nLưu workflow tạo ảnh chủ đạo rồi image-to-video, thay brief và ảnh cho từng tập nhưng giữ cấu hình đã duyệt.\n\nBẮT ĐẦU\nBắt đầu từ desktop/portable hoặc template chính chủ; cài từng model/node cần thiết.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCustom node có thể chạy code. Partner/API node có thể tính phí và gửi dữ liệu ra ngoài; local core và cloud là hai cách triển khai khác nhau.","canonical_url":"https://github.com/Comfy-Org/ComfyUI","repository_url":"https://github.com/Comfy-Org/ComfyUI","documentation_url":"https://raw.githubusercontent.com/Comfy-Org/ComfyUI/master/README.md","owner_name":"Comfy-Org","license":"GPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":7,"categories":["image","video","audio","automation"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Biến cách tạo hình và video của bạn thành workflow nhìn thấy được, lưu lại được. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Biến cách tạo hình và video của bạn thành workflow nhìn thấy được, lưu lại được.","highlights":["Workflow hình, video, audio và 3D; lưu/đọc JSON và subgraph.","Có template, App Mode và API để tích hợp pipeline.","Quản lý hàng đợi, bộ nhớ và chạy lại phần thay đổi trong đồ thị."],"example":"Lưu workflow tạo ảnh chủ đạo rồi image-to-video, thay brief và ảnh cho từng tập nhưng giữ cấu hình đã duyệt.","setup":"Bắt đầu từ desktop/portable hoặc template chính chủ; cài từng model/node cần thiết.","limitations":"Custom node có thể chạy code. Partner/API node có thể tính phí và gửi dữ liệu ra ngoài; local core và cloud là hai cách triển khai khác nhau.","github":{"stars":131343,"forks":15478,"observedAt":"2026-09-03T16:08:48.098Z","url":"https://github.com/Comfy-Org/ComfyUI","pushedAt":"2026-09-03T12:15:09Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Comfy-Org/ComfyUI/master/README.md","observedAt":"2026-09-03T16:10:23.185Z","sha256":"4ea2b6d7c84db2fd361ac1af754ab0c4ac401982bae2a8fcb298b8d9ea827ffe"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Comfy-Org/ComfyUI:metadata","source_url":"https://github.com/Comfy-Org/ComfyUI","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Aace-step%2FACE-Step-1.5%20repo%3Afacebookresearch%2Faudiocraft%20repo%3AAnjok07%2Fultimatevocalremovergui%20repo%3Aaudacity%2Faudacity%20repo%3AComfy-Org%2FComfyUI%20repo%3AAUTOMATIC1111%2Fstable-diffusion-webui%20repo%3Alllyasviel%2FFooocus%20repo%3Ainvoke-ai%2FInvokeAI&per_page=100","stars":131343,"forks":15478,"license":"GPL-3.0"},"fetched_at":"2026-09-03T16:08:48.098Z"},{"source_type":"github","source_identifier":"Comfy-Org/ComfyUI:readme:4ea2b6d7c84db2fd361ac1af754ab0c4ac401982bae2a8fcb298b8d9ea827ffe","source_url":"https://raw.githubusercontent.com/Comfy-Org/ComfyUI/master/README.md","raw_metadata":{"sha256":"4ea2b6d7c84db2fd361ac1af754ab0c4ac401982bae2a8fcb298b8d9ea827ffe","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:23.185Z"}],"expected":null},{"identity":"repo:https://github.com/openai/whisper","slug":"whisper-a03c2f78","name":"Whisper","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Từ voice đã thu đến văn bản để sửa kịch bản và bắt đầu làm phụ đề.","description":"Whisper là mô hình nhận dạng giọng nói đa ngôn ngữ của OpenAI. Nó biến audio thành chữ, nhận diện ngôn ngữ và có tác vụ dịch lời nói. Đây là nền tảng quen thuộc trong workflow video nhưng không phải công cụ tạo voice từ văn bản.","long_description":"ĐIỂM NỔI BẬT\n• Có nhiều cỡ model để cân bằng tốc độ, bộ nhớ và độ chính xác.\n• Có mô hình đa ngôn ngữ và các bản .en dành riêng tiếng Anh.\n• Code và trọng số được chính chủ phát hành theo MIT.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nChép lời voice của bạn, sửa từ chuyên ngành rồi đưa kết quả sang bước căn timestamp và biên tập phụ đề.\n\nBẮT ĐẦU\nChuẩn bị Python, PyTorch và FFmpeg; chọn model theo phần cứng và ngôn ngữ thực tế.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCó thể nhận sai hoặc sinh chữ ở đoạn nhiễu/im lặng. Đừng dùng bản .en cho tiếng Việt; timestamp cần kiểm tra, hiệu năng benchmark không phải tốc độ đảm bảo trên mọi máy.","canonical_url":"https://github.com/openai/whisper","repository_url":"https://github.com/openai/whisper","documentation_url":"https://raw.githubusercontent.com/openai/whisper/main/README.md","owner_name":"openai","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":8,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Từ voice đã thu đến văn bản để sửa kịch bản và bắt đầu làm phụ đề. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Từ voice đã thu đến văn bản để sửa kịch bản và bắt đầu làm phụ đề.","highlights":["Có nhiều cỡ model để cân bằng tốc độ, bộ nhớ và độ chính xác.","Có mô hình đa ngôn ngữ và các bản .en dành riêng tiếng Anh.","Code và trọng số được chính chủ phát hành theo MIT."],"example":"Chép lời voice của bạn, sửa từ chuyên ngành rồi đưa kết quả sang bước căn timestamp và biên tập phụ đề.","setup":"Chuẩn bị Python, PyTorch và FFmpeg; chọn model theo phần cứng và ngôn ngữ thực tế.","limitations":"Có thể nhận sai hoặc sinh chữ ở đoạn nhiễu/im lặng. Đừng dùng bản .en cho tiếng Việt; timestamp cần kiểm tra, hiệu năng benchmark không phải tốc độ đảm bảo trên mọi máy.","github":{"stars":108357,"forks":13132,"observedAt":"2026-09-03T16:08:35.124Z","url":"https://github.com/openai/whisper","pushedAt":"2026-08-31T17:19:19Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/openai/whisper/main/README.md","observedAt":"2026-09-03T16:10:11.061Z","sha256":"38c180c2a8d8ba628a3e131ad42bf06c8a51bb681efb30fbe28d5a0f4b65f288"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"openai/whisper:metadata","source_url":"https://github.com/openai/whisper","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ABlaizzy%2Fmlx-video%20repo%3Aopenai%2Fwhisper%20repo%3Am-bain%2FwhisperX%20repo%3ASYSTRAN%2Ffaster-whisper%20repo%3Aggml-org%2Fwhisper.cpp%20repo%3AFunAudioLLM%2FCosyVoice%20repo%3ASWivid%2FF5-TTS%20repo%3Ahexgrad%2Fkokoro&per_page=100","stars":108357,"forks":13132,"license":"MIT"},"fetched_at":"2026-09-03T16:08:35.124Z"},{"source_type":"github","source_identifier":"openai/whisper:readme:38c180c2a8d8ba628a3e131ad42bf06c8a51bb681efb30fbe28d5a0f4b65f288","source_url":"https://raw.githubusercontent.com/openai/whisper/main/README.md","raw_metadata":{"sha256":"38c180c2a8d8ba628a3e131ad42bf06c8a51bb681efb30fbe28d5a0f4b65f288","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:11.061Z"}],"expected":null},{"identity":"repo:https://github.com/m-bain/whisperx","slug":"whisperx-5db3f0f6","name":"WhisperX","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Muốn chữ bật đúng lúc người nói? Cần timestamp mức từ, không chỉ một đoạn transcript.","description":"WhisperX bổ sung căn chỉnh âm vị, chia theo hoạt động giọng nói và nhận diện lượt người nói quanh Whisper. Nó phù hợp bước tạo timeline phụ đề hoặc gắn chuyển động vào lời đọc. Tốc độ và độ khớp mà tác giả công bố vẫn phụ thuộc model, ngôn ngữ và máy.","long_description":"ĐIỂM NỔI BẬT\n• Căn timestamp mức từ bằng forced alignment.\n• Xử lý theo batch với faster-whisper và lọc hoạt động giọng nói.\n• Có speaker diarization và đầu ra hỗ trợ phụ đề tô sáng từ.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nDùng voice đã duyệt để tạo mốc từ, nhóm lại thành các câu ngắn cho phụ đề Shorts rồi nghe soát lần cuối.\n\nBẮT ĐẦU\nƯu tiên bản PyPI ổn định; kiểm tra model alignment cho ngôn ngữ cần dùng. Diarization cần chấp nhận điều khoản model liên quan.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông coi nhận diện người nói là biết danh tính thật. Từ số, nhiễu và model alignment không phù hợp có thể lệch; token tải model phải giữ kín.","canonical_url":"https://github.com/m-bain/whisperX","repository_url":"https://github.com/m-bain/whisperX","documentation_url":"https://raw.githubusercontent.com/m-bain/whisperX/main/README.md","owner_name":"m-bain","license":"BSD-2-Clause","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":9,"categories":["audio","video"],"primaryCategory":"audio","selectionReason":"Phù hợp Voice & Âm nhạc: Muốn chữ bật đúng lúc người nói? Cần timestamp mức từ, không chỉ một đoạn transcript. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Muốn chữ bật đúng lúc người nói? Cần timestamp mức từ, không chỉ một đoạn transcript.","highlights":["Căn timestamp mức từ bằng forced alignment.","Xử lý theo batch với faster-whisper và lọc hoạt động giọng nói.","Có speaker diarization và đầu ra hỗ trợ phụ đề tô sáng từ."],"example":"Dùng voice đã duyệt để tạo mốc từ, nhóm lại thành các câu ngắn cho phụ đề Shorts rồi nghe soát lần cuối.","setup":"Ưu tiên bản PyPI ổn định; kiểm tra model alignment cho ngôn ngữ cần dùng. Diarization cần chấp nhận điều khoản model liên quan.","limitations":"Không coi nhận diện người nói là biết danh tính thật. Từ số, nhiễu và model alignment không phù hợp có thể lệch; token tải model phải giữ kín.","github":{"stars":23874,"forks":2407,"observedAt":"2026-09-03T16:08:35.124Z","url":"https://github.com/m-bain/whisperX","pushedAt":"2026-08-30T15:40:47Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/m-bain/whisperX/main/README.md","observedAt":"2026-09-03T16:10:13.067Z","sha256":"d68ee671da04b2f2c8a1242bb129f4ac72ab6e42f8eb6ba8ef3e53c6d2c03a11"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"m-bain/whisperX:metadata","source_url":"https://github.com/m-bain/whisperX","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3ABlaizzy%2Fmlx-video%20repo%3Aopenai%2Fwhisper%20repo%3Am-bain%2FwhisperX%20repo%3ASYSTRAN%2Ffaster-whisper%20repo%3Aggml-org%2Fwhisper.cpp%20repo%3AFunAudioLLM%2FCosyVoice%20repo%3ASWivid%2FF5-TTS%20repo%3Ahexgrad%2Fkokoro&per_page=100","stars":23874,"forks":2407,"license":"BSD-2-Clause"},"fetched_at":"2026-09-03T16:08:35.124Z"},{"source_type":"github","source_identifier":"m-bain/whisperX:readme:d68ee671da04b2f2c8a1242bb129f4ac72ab6e42f8eb6ba8ef3e53c6d2c03a11","source_url":"https://raw.githubusercontent.com/m-bain/whisperX/main/README.md","raw_metadata":{"sha256":"d68ee671da04b2f2c8a1242bb129f4ac72ab6e42f8eb6ba8ef3e53c6d2c03a11","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:13.067Z"}],"expected":null},{"identity":"repo:https://github.com/n8n-io/n8n","slug":"n8n-3e3596be","name":"n8n","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Nối các công cụ thành dây chuyền nội dung có điểm dừng để người thật duyệt.","description":"n8n dùng canvas và các tích hợp để xây workflow nhiều bước, có thể kết hợp AI, dữ liệu và code khi cần. Với creator, giá trị là giảm thao tác lặp giữa nghiên cứu, soạn bài và phân phối; không nhất thiết giao quyền tự đăng ngay từ đầu.","long_description":"ĐIỂM NỔI BẬT\n• Kết nối nhiều dịch vụ, model và dữ liệu trong workflow.\n• Có nhánh logic, agent và bước human approval được chính chủ mô tả.\n• Có lựa chọn self-host/cloud và tài liệu mẫu workflow.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nĐọc nguồn RSS, tạo bản nháp có link nguồn rồi gửi vào hàng chờ duyệt trước khi lên lịch đăng.\n\nBẮT ĐẦU\nThử workflow nhỏ, chọn cloud hoặc Docker và cấu hình quyền tối thiểu cho từng kết nối.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nn8n là fair-code/source-available, không phải MIT. Một số khả năng quản trị thuộc gói riêng; self-host vẫn có chi phí máy và dịch vụ AI.","canonical_url":"https://github.com/n8n-io/n8n","repository_url":"https://github.com/n8n-io/n8n","documentation_url":"https://raw.githubusercontent.com/n8n-io/n8n/master/README.md","owner_name":"n8n-io","license":"Sustainable Use License / n8n Enterprise License; kiểm tra điều kiện nhúng, bán dịch vụ.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":10,"categories":["automation","social","content"],"primaryCategory":"automation","selectionReason":"Phù hợp Tự động hóa: Nối các công cụ thành dây chuyền nội dung có điểm dừng để người thật duyệt. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Nối các công cụ thành dây chuyền nội dung có điểm dừng để người thật duyệt.","highlights":["Kết nối nhiều dịch vụ, model và dữ liệu trong workflow.","Có nhánh logic, agent và bước human approval được chính chủ mô tả.","Có lựa chọn self-host/cloud và tài liệu mẫu workflow."],"example":"Đọc nguồn RSS, tạo bản nháp có link nguồn rồi gửi vào hàng chờ duyệt trước khi lên lịch đăng.","setup":"Thử workflow nhỏ, chọn cloud hoặc Docker và cấu hình quyền tối thiểu cho từng kết nối.","limitations":"n8n là fair-code/source-available, không phải MIT. Một số khả năng quản trị thuộc gói riêng; self-host vẫn có chi phí máy và dịch vụ AI.","github":{"stars":203230,"forks":60538,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/n8n-io/n8n","pushedAt":"2026-09-03T16:08:53Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/n8n-io/n8n/master/README.md","observedAt":"2026-09-03T16:10:41.602Z","sha256":"75c64f04b8b1e7d435496f6ebd2dbf3ea5ff7d3ff3d944d7fcf98cf1a7df2242"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"n8n-io/n8n:metadata","source_url":"https://github.com/n8n-io/n8n","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":203230,"forks":60538,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"n8n-io/n8n:readme:75c64f04b8b1e7d435496f6ebd2dbf3ea5ff7d3ff3d944d7fcf98cf1a7df2242","source_url":"https://raw.githubusercontent.com/n8n-io/n8n/master/README.md","raw_metadata":{"sha256":"75c64f04b8b1e7d435496f6ebd2dbf3ea5ff7d3ff3d944d7fcf98cf1a7df2242","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:41.602Z"}],"expected":null}]'::jsonb) loop
  select * into existing from public.resources where external_identity=x->>'identity' for update;
  already:=found and existing.import_metadata->>'creatorImportHash'='70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf';
  if already then continue; end if;
  if existing.id is not null and (existing.id::text is distinct from x->>'expected' or existing.editorial_revision<>0 or existing.status<>'CANDIDATE') then raise exception 'Candidate changed since snapshot: %',x->>'identity'; end if;
  if existing.id is null and x->>'expected' is not null then raise exception 'Candidate disappeared since snapshot'; end if;
  if existing.id is null then
    insert into public.resources(external_identity,slug,type,name,canonical_url) values(x->>'identity',x->>'slug',(x->>'type')::public.resource_type,x->>'name',x->>'canonical_url') returning id into rid;
  else rid:=existing.id; end if;
  update public.resources set name=x->>'name',type=(x->>'type')::public.resource_type,tagline=x->>'tagline',description=x->>'description',long_description=x->>'long_description',canonical_url=x->>'canonical_url',repository_url=x->>'repository_url',documentation_url=x->>'documentation_url',owner_name=x->>'owner_name',license=x->>'license',import_metadata=import_metadata||(x->'import_metadata')||jsonb_build_object('creatorImportHash','70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf'),last_source_update_at=(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz,editorial_revision=editorial_revision+1,updated_at=now() where id=rid;
  for s in select value from jsonb_array_elements(x->'sources') loop
    insert into public.resource_sources(resource_id,source_type,source_identifier,source_url,raw_metadata,fetched_at) values(rid,s->>'source_type',s->>'source_identifier',s->>'source_url',s->'raw_metadata',(s->>'fetched_at')::timestamptz) on conflict(resource_id,source_type,source_identifier) do update set source_url=excluded.source_url,raw_metadata=excluded.raw_metadata,fetched_at=excluded.fetched_at;
  end loop;
  insert into public.resource_metric_snapshots(resource_id,source_type,metric_key,metric_value,captured_at) values(rid,'github','stars',(x#>>'{import_metadata,creatorCatalog,github,stars}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz),(rid,'github','forks',(x#>>'{import_metadata,creatorCatalog,github,forks}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz) on conflict do nothing;
  insert into public.resource_evidence_jobs(resource_id) values(rid) on conflict do nothing;
end loop;
end $creator_import$;
commit;
